// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContestContentCommand) predicate.ContestContentCommand {
	return predicate.ContestContentCommand(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContestContentCommand) predicate.ContestContentCommand {
	return predicate.ContestContentCommand(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContestContentCommand) predicate.ContestContentCommand {
	return predicate.ContestContentCommand(sql.NotPredicates(p))
}
